function (api) {
  var html = api.responses.page || '';
  var marker = 'eval(function(p,a,c,k,e,d)';
  var m = html.indexOf(marker);
  if (m < 0) return [];
  var s = html.slice(m);
  var ps = s.indexOf("}('");
  if (ps < 0) return [];
  ps += 3;
  var b0 = s.indexOf("',", ps);
  if (b0 < 0) return [];
  var p = s.slice(ps, b0);
  var i = b0 + 2;
  var aStr = readDigits(s, i);
  i += aStr.length;
  if (s[i] === ',') i++;
  var cStr = readDigits(s, i);
  i += cStr.length;
  if (s[i] === ',') i++;
  if (s[i] === "'") i++;
  var kEnd = s.indexOf("'.split('|')", i);
  if (kEnd < 0) return [];
  var k = s.slice(i, kEnd).split('|');
  var a = Number(aStr);
  var c = Number(cStr);
  if (!a || !c) return [];
  var chars = '0123456789abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ';
  var d = {};
  for (var n = 0; n < c; n++) {
    var key = packerKey(n, a, chars);
    d[key] = k[n] || key;
  }
  var text = '';
  var buf = '';
  var token = false;
  for (var j = 0; j < p.length; j++) {
    var ch = p[j];
    var isWord = isWordChar(ch);
    if (isWord !== token) {
      if (token) text += d[buf] !== undefined ? d[buf] : buf;
      else text += buf;
      buf = ch;
      token = isWord;
    } else {
      buf += ch;
    }
  }
  if (buf) text += token ? (d[buf] !== undefined ? d[buf] : buf) : buf;
  var path = jsonString(text, 'path');
  var files = jsonArray(text, 'files');
  var e = jsonString(text, 'e');
  var mm = jsonString(text, 'm');
  if (!path || files.length === 0) return [];
  var out = [];
  for (var x = 0; x < files.length; x++) {
    var u = 'https://us.hamreus.com' + path + files[x];
    if (e || mm) u += '?e=' + e + '&m=' + mm;
    out.push(u);
  }
  return out;

  function readDigits(str, at) {
    var out = '';
    while (at < str.length && str[at] >= '0' && str[at] <= '9') {
      out += str[at];
      at++;
    }
    return out;
  }

  function isWordChar(ch) {
    return (ch >= 'a' && ch <= 'z') || (ch >= 'A' && ch <= 'Z') || (ch >= '0' && ch <= '9') || ch === '_';
  }

  function packerKey(value, base, alphabet) {
    var out = '';
    for (;;) {
      var rem = value % base;
      out = (rem > 35 ? String.fromCharCode(rem + 29) : alphabet[rem]) + out;
      value = Math.floor(value / base);
      if (value === 0) break;
    }
    return out;
  }

  function jsonString(text, key) {
    var marker = '"' + key + '":"';
    var a = text.indexOf(marker);
    if (a < 0) return '';
    a += marker.length;
    var b = text.indexOf('"', a);
    return b < 0 ? '' : text.slice(a, b);
  }

  function jsonArray(text, key) {
    var marker = '"' + key + '":[';
    var a = text.indexOf(marker);
    if (a < 0) return [];
    var out = [];
    var i = a + marker.length;
    for (;;) {
      if (text[i] === '"') {
        var j = text.indexOf('"', i + 1);
        if (j < 0) break;
        out.push(text.slice(i + 1, j));
        i = j + 1;
      } else if (text[i] === ']' || text[i] === undefined) {
        break;
      } else {
        i++;
      }
    }
    return out;
  }
}
